// BenchmarkMetrics Mesures d'un seul modèle ; les champs dépendent de l'étape (empreinte : eer, top1, précision, rappel… ; transcription : wer, cer… ; diarisation : der et ses trois composantes). Jamais comparables en score brut d'un modèle à l'autre. Bout en bout : cpwer (erreurs de mots avec attribution des locuteurs), wer (sans attribution) et der des mêmes sorties.
type BenchmarkMetrics struct {
	// Cer Character Error Rate (transcription).
	Cer *float64 `json:"cer,omitempty"`

	// CerSkippedClips Clips trop longs pour la comparaison par caractère, laissés hors du CER.
	CerSkippedClips *int `json:"cer_skipped_clips,omitempty"`
	CharacterErrors *int `json:"character_errors,omitempty"`

	// Clips Transcription : clips (et pistes) mesurés.
	Clips *int `json:"clips,omitempty"`

	// CollarSeconds Tolérance autour de chaque borne de référence.
	CollarSeconds    *float64 `json:"collar_seconds,omitempty"`
	ConfusionRate    *float64 `json:"confusion_rate,omitempty"`
	ConfusionSeconds *float64 `json:"confusion_seconds,omitempty"`
	CpWordErrors     *int     `json:"cp_word_errors,omitempty"`

	// Cpwer Bout en bout : WER avec attribution des locuteurs (cpWER).
	Cpwer *float64 `json:"cpwer,omitempty"`

	// Der Diarization Error Rate : parole manquée + fausse alarme + confusion, rapportées à la parole de référence.
	Der                    *float64 `json:"der,omitempty"`
	Eer                    *float64 `json:"eer,omitempty"`
	EerThreshold           *float64 `json:"eer_threshold,omitempty"`
	FalseAlarmRate         *float64 `json:"false_alarm_rate,omitempty"`
	FalseAlarmSeconds      *float64 `json:"false_alarm_seconds,omitempty"`
	FalseNegatives         *int     `json:"false_negatives,omitempty"`
	FalsePositives         *int     `json:"false_positives,omitempty"`
	GenuineMeanScore       *float64 `json:"genuine_mean_score,omitempty"`
	GenuineTrials          *int     `json:"genuine_trials,omitempty"`
	IgnoredDimension       *int     `json:"ignored_dimension,omitempty"`
	ImpostorMeanScore      *float64 `json:"impostor_mean_score,omitempty"`
	ImpostorTrials         *int     `json:"impostor_trials,omitempty"`
	MissedSpeechRate       *float64 `json:"missed_speech_rate,omitempty"`
	MissedSpeechSeconds    *float64 `json:"missed_speech_seconds,omitempty"`
	ModelSpeakers          *int     `json:"model_speakers,omitempty"`
	Persons                *int     `json:"persons,omitempty"`
	Precision              *float64 `json:"precision,omitempty"`
	Recall                 *float64 `json:"recall,omitempty"`
	ReferenceChars         *int     `json:"reference_chars,omitempty"`
	ReferenceSpeakers      *int     `json:"reference_speakers,omitempty"`
	ReferenceSpeechSeconds *float64 `json:"reference_speech_seconds,omitempty"`
	ReferenceWords         *int     `json:"reference_words,omitempty"`
	References             *int     `json:"references,omitempty"`

	// SkippedClips Diarisation : clips trop longs, laissés hors du calcul.
	SkippedClips  *int     `json:"skipped_clips,omitempty"`
	Tests         *int     `json:"tests,omitempty"`
	Top1Accuracy  *float64 `json:"top1_accuracy,omitempty"`
	TruePositives *int     `json:"true_positives,omitempty"`

	// Wer Word Error Rate (transcription), micro-moyenne sur les clips.
	Wer        *float64 `json:"wer,omitempty"`
	WordErrors *int     `json:"word_errors,omitempty"`
}

